  GeneralRecipe(id: "n08_301", title: "Soğuk yeşil çay (ballı limonlu)", category: "İçecekler", ingredients: ["2 poşet yeşil çay", "4 su bardağı 80 °C su", "1 limon", "2 yemek kaşığı bal", "4–5 dal nane"], steps: ["Suyu kaynatıp 2 dakika soğutun.", "Çayı 3 dakika demleyin.", "Balı ekleyip soğutun.", "Limon ve nane ekleyin.", "Buzla servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Yeşil çayı kaynar suda demlemek acılaştırır."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün."),
