  GeneralRecipe(id: "n08_305", title: "Tarçınlı elma çayı (meyveli)", category: "İçecekler", ingredients: ["2 elma", "1 çubuk tarçın", "4 karanfil", "4 su bardağı su", "1 yemek kaşığı bal"], steps: ["Elmaları dilimleyin.", "Su ve baharatlarla 10 dakika kaynatın.", "5 dakika demleyin.", "Süzüp bal ekleyin.", "Sıcak veya soğuk servis edin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Kışın sıcak, yazın soğuk içilebilir."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n09_001", title: "Kuzu kapama", category: "Et yemekleri", ingredients: ["1 kg kuzu eti (kemikli)", "10 taze soğan", "1 marul", "1 demet dereotu", "2 yemek kaşığı tereyağı", "1 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Eti tencerenin dibine yerleştirin.", "Taze soğan ve marulu iri doğrayıp üzerine koyun.", "Dereotu, tereyağı, tuz ve suyu ekleyin.", "Kapağı kapalı kısık ateşte 2 saat pişirin.", "Dereotuyla servis edin."], minutes: 140, servings: 6, prepMinutes: 20, cookMinutes: 120, difficulty: "Orta", tips: ["Bahar yemeğidir; sebzeler eti yumuşatır."], serving: "Pilavla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_002", title: "Kıymalı patates musakka", category: "Et yemekleri", ingredients: ["500 g patates", "300 g kıyma", "1 soğan", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz"], steps: ["Patatesleri halka kesip fırında 15 dakika ön pişirin.", "Kıymayı soğan ve salçayla kavurun.", "Kaba patates ve kıymayı kat kat dizin.", "Domates dilimleri ve 1 bardak sıcak su ekleyin.", "180 °C'de 25 dakika pişirin."], minutes: 60, servings: 4, prepMinutes: 20, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 180, tips: ["Patatesi ön pişirmek süreyi kısaltır."], serving: "Yoğurtla.", storage: "Buzdolabında 3 gün."),
