  GeneralRecipe(id: "n09_201", title: "Tavada nohut köftesi", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış nohut", "1 soğan", "3 yemek kaşığı galeta unu", "1 yumurta", "1 tatlı kaşığı kimyon, tuz", "2 yemek kaşığı sıvı yağ"], steps: ["Nohutu ezin.", "Rendelenmiş soğan, galeta unu, yumurta ve baharatla yoğurun.", "Köfte şekli verin.", "Tavada her yüzü 3 dakika pişirin.", "Yoğurtla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Etsiz protein kaynağıdır."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_202", title: "Etsiz pişmiş çiğ köfte", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı kırmızı mercimek", "1 su bardağı ince bulgur", "2 yemek kaşığı biber salçası", "1 soğan", "4 dal taze soğan", "Yarım demet maydanoz", "4 yemek kaşığı zeytinyağı", "1 tatlı kaşığı isot, kimyon, tuz"], steps: ["Mercimeği 2,5 bardak suyla dağılana kadar pişirin.", "Ocaktan alıp bulguru ekleyin, 20 dakika şişirin.", "Salça, soğan ve baharatlarla yoğurun.", "Yeşillikleri ekleyin.", "Sıkıp şekil verin."], minutes: 45, servings: 6, prepMinutes: 30, cookMinutes: 15, difficulty: "Kolay", tips: ["Etsiz ve pişmiş versiyondur."], serving: "Marul ve limonla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_203", title: "Nohutlu tavuk yahni", category: "Bakliyat yemekleri", ingredients: ["300 g tavuk but", "2 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "2 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Tavuğu küp doğrayıp tereyağında mühürleyin.", "Soğan ve salçayı ekleyin.", "Nohut ve suyu ekleyin.", "25 dakika pişirin.", "Pilavla servis edin."], minutes: 45, servings: 4, prepMinutes: 10, cookMinutes: 35, difficulty: "Kolay", tips: ["Nohut ve tavuk tam protein sağlar."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_204", title: "Yeşil mercimekli ıspanak", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "500 g ıspanak", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Soğanı kavurup salçayı ekleyin.", "Mercimeği ekleyin.", "Ispanağı ekleyip soldurun.", "15 dakika pişirin.", "Yoğurtla servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Demir açısından zengin bir yemektir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_205", title: "Börülceli pazı kavurma", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı haşlanmış börülce", "1 demet pazı", "1 soğan", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı pul biber, tuz"], steps: ["Soğan ve sarımsağı yağda kavurun.", "Doğranmış pazıyı ekleyin.", "Börülceyi ekleyin.", "10 dakika pişirin.", "Pul biberle servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Ege mutfağından hafif bir yemektir."], serving: "Ilık.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_206", title: "Barbunyalı bulgur pilavı", category: "Bakliyat yemekleri", ingredients: ["1,5 su bardağı bulgur", "1 su bardağı haşlanmış barbunya", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Soğanı kavurup salçayı ekleyin.", "Bulgur ve barbunyayı ekleyin.", "Su ve tuzla 15 dakika pişirin.", "10 dakika demlendirin.", "Yoğurtla servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Tek başına öğün olabilir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_207", title: "Mercimek çorbası (süzme, klasik)", category: "Bakliyat yemekleri", ingredients: ["1,5 su bardağı kırmızı mercimek", "1 soğan", "1 havuç", "1 patates", "2 yemek kaşığı tereyağı", "1 yemek kaşığı un", "8 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Soğanı tereyağında kavurup unu ekleyin.", "Mercimek ve sebzeleri ekleyin.", "Su ve tuzla 30 dakika pişirin.", "Blenderdan geçirin.", "Kırmızı biberli tereyağıyla servis edin."], minutes: 45, servings: 6, prepMinutes: 10, cookMinutes: 35, difficulty: "Kolay", tips: ["Un çorbaya restoran kıvamı verir."], serving: "Limonla.", storage: "Buzdolabında 3 gün."),
