  GeneralRecipe(id: "n09_301", title: "Yulaflı muzlu kahvaltı kurabiyesi", category: "Kahvaltılıklar", ingredients: ["2 muz", "1,5 su bardağı yulaf", "2 yemek kaşığı fıstık ezmesi", "2 yemek kaşığı kuru üzüm", "1 çay kaşığı tarçın"], steps: ["Fırını 180 °C'ye ısıtın.", "Muzları ezin.", "Diğer malzemeleri ekleyin.", "Kaşıkla tepsiye bırakın.", "15 dakika pişirin."], minutes: 25, servings: 12, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 180, tips: ["Şekersiz kahvaltı kurabiyesidir."], serving: "Sütle.", storage: "Kapalı kapta 3 gün."),
