  GeneralRecipe(id: "n09_306", title: "Patatesli peynirli börek (tavada)", category: "Kahvaltılıklar", ingredients: ["2 yufka", "2 haşlanmış patates", "100 g beyaz peynir", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı tereyağı"], steps: ["Patates ve peyniri ezip karıştırın.", "Yumurta ve sütü çırpın.", "Yufkaları tavaya serip sosla ıslatın, harcı yayın.", "Kapatıp kısık ateşte 10 dakika pişirin.", "Ters çevirip 8 dakika daha pişirin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Fırına gerek kalmadan pratik börek."], serving: "Sıcak.", storage: "Taze tüketin."),
