  GeneralRecipe(id: "n09_401", title: "Tavuklu pilav (nohutlu, sokak usulü)", category: "Pilavlar", ingredients: ["2 su bardağı pirinç", "1 tavuk göğsü", "1 su bardağı haşlanmış nohut", "3 yemek kaşığı tereyağı", "3 su bardağı tavuk suyu", "1 tatlı kaşığı tuz"], steps: ["Tavuğu haşlayıp didikleyin, suyunu saklayın.", "Pirinci tereyağında kavurun.", "Nohut ve tavuk suyunu ekleyin.", "15 dakika pişirin.", "Tavukla servis edin."], minutes: 55, servings: 6, prepMinutes: 15, cookMinutes: 40, difficulty: "Kolay", tips: ["Haşlama suyu pilava lezzet verir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
