  GeneralRecipe(id: "n09_403", title: "Mantarlı pirinç pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı pirinç", "200 g mantar", "1 soğan", "2 yemek kaşığı tereyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Mantar ve soğanı tereyağında soteleyin.", "Pirinci ekleyip kavurun.", "Su ve tuzla 15 dakika pişirin.", "Demlendirin.", "Servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Mantar pilava umami tat verir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n09_404", title: "Havuçlu kuru üzümlü pilav", category: "Pilavlar", ingredients: ["1,5 su bardağı pirinç", "2 havuç (jülyen)", "2 yemek kaşığı kuru üzüm", "2 yemek kaşığı tereyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz, tarçın"], steps: ["Havucu tereyağında soteleyin.", "Pirinci ekleyip kavurun.", "Su, üzüm, tuz ve tarçınla pişirin.", "Demlendirin.", "Servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Özbek pilavından esinlenmiştir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n09_405", title: "Ispanaklı pirinç pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı pirinç", "300 g ıspanak", "1 soğan", "2 yemek kaşığı tereyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Soğanı tereyağında kavurun.", "Pirinci ekleyin.", "Su ve tuzla 10 dakika pişirin.", "Ispanağı ekleyip 5 dakika daha pişirin.", "Demlendirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Ispanak yeşil renk ve demir katar."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n09_501", title: "Yayla çorbası (pirinçli, naneli)", category: "Çorbalar", ingredients: ["3 yemek kaşığı pirinç", "1,5 su bardağı yoğurt", "1 yumurta sarısı", "1 yemek kaşığı un", "5 su bardağı su", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı nane, tuz"], steps: ["Pirinci suyla 15 dakika pişirin.", "Yoğurt, yumurta ve unu çırpın.", "Sıcak sudan ekleyerek ılıştırın.", "Tencereye ekleyip karıştırarak kaynatın.", "Naneli tereyağıyla servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Terbiye ılıştırılmazsa kesilir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
