  GeneralRecipe(id: "n09_503", title: "Kabak çorbası (kremasız)", category: "Çorbalar", ingredients: ["4 kabak", "1 patates", "1 soğan", "2 yemek kaşığı zeytinyağı", "5 su bardağı su", "1 tatlı kaşığı tuz"], steps: ["Soğanı yağda kavurun.", "Kabak ve patatesi ekleyin.", "Suyla 15 dakika pişirin.", "Blenderdan geçirin.", "Dereotuyla servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Patates kremayı gereksiz kılar."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
