  GeneralRecipe(id: "n10_101", title: "Zeytinyağlı enginar kalbi mezesi", category: "Mezeler", ingredients: ["6 enginar kalbi", "1 havuç", "1 patates", "1 limon", "4 yemek kaşığı zeytinyağı", "Yarım demet dereotu", "1 tatlı kaşığı şeker, tuz"], steps: ["Enginarları limonlu suda bekletin.", "Havuç ve patatesi küp doğrayın.", "Enginarlara yerleştirip tencereye dizin.", "Yağ, limon, şeker, tuz ve 1 bardak suyla 25 dakika pişirin.", "Dereotuyla soğuk servis edin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Limonlu su kararmayı önler."], serving: "Soğuk.", storage: "Buzdolabında 2–3 gün."),
  GeneralRecipe(id: "n10_102", title: "Zeytinyağlı lahana sarma", category: "Mezeler", ingredients: ["1 lahana", "1 su bardağı pirinç", "2 soğan", "Yarım su bardağı zeytinyağı", "1 tatlı kaşığı nane, pul biber, tuz", "1 limon"], steps: ["Lahana yapraklarını haşlayın.", "Soğan, pirinç ve baharatlarla harç yapın.", "Yapraklara sarın.", "Tencereye dizip yağ, limon ve 2 bardak su ekleyin.", "40 dakika pişirip soğutun."], minutes: 80, servings: 6, prepMinutes: 40, cookMinutes: 40, difficulty: "Orta", tips: ["Kışlık bir mezedir."], serving: "Soğuk.", storage: "Buzdolabında 2–3 gün."),
  GeneralRecipe(id: "n10_103", title: "Fava ezmesi (dereotlu)", category: "Mezeler", ingredients: ["1 su bardağı kuru bakla", "1 soğan", "4 yemek kaşığı zeytinyağı", "Yarım demet dereotu", "1 tatlı kaşığı tuz"], steps: ["Baklayı soğanla 40 dakika pişirin.", "Blenderdan geçirin.", "Zeytinyağı ve tuz ekleyin.", "Kaba döküp soğutun.", "Dereotuyla servis edin."], minutes: 50, servings: 4, prepMinutes: 10, cookMinutes: 40, difficulty: "Kolay", tips: ["Soğuyunca dilimlenir."], serving: "Soğuk.", storage: "Buzdolabında 2–3 gün."),
  GeneralRecipe(id: "n10_104", title: "Ezme biber salatası (Antep usulü)", category: "Mezeler", ingredients: ["2 domates", "2 köz biber", "1 soğan", "Yarım demet maydanoz", "2 yemek kaşığı nar ekşisi", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı isot, tuz"], steps: ["Tüm sebzeleri bıçakla çok ince kıyın.", "Nar ekşisi ve yağı ekleyin.", "İsot ve tuzla tatlandırın.", "Karıştırın.", "Soğuk servis edin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Közlü biber mezeye derinlik katar."], serving: "Soğuk.", storage: "Buzdolabında 2–3 gün."),
  GeneralRecipe(id: "n10_105", title: "Yoğurtlu havuç tarator", category: "Mezeler", ingredients: ["3 havuç", "1,5 su bardağı yoğurt", "1 diş sarımsak", "2 yemek kaşığı ceviz", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Havucu rendeleyip yağda 6 dakika soteleyin.", "Soğutun.", "Yoğurt ve sarımsakla karıştırın.", "Ceviz ekleyin.", "Servis edin."], minutes: 20, servings: 4, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Havucu soteleyince tatlanır."], serving: "Soğuk.", storage: "Buzdolabında 2–3 gün."),
  GeneralRecipe(id: "n10_106", title: "Antakya usulü fıstıklı humus", category: "Mezeler", ingredients: ["2 su bardağı haşlanmış nohut", "3 yemek kaşığı tahin", "1 limon", "1 diş sarımsak", "2 yemek kaşığı Antep fıstığı", "3 yemek kaşığı zeytinyağı", "1 çay kaşığı kimyon, tuz"], steps: ["Nohut, tahin, limon, sarımsak ve baharatları robotta çekin.", "Buzlu suyla kıvamı ayarlayın.", "Tabağa yayın.", "Kıyılmış fıstık serpin.", "Zeytinyağıyla servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Fıstık humusa renk ve çıtırlık katar."], serving: "Soğuk.", storage: "Buzdolabında 2–3 gün."),
  GeneralRecipe(id: "n10_107", title: "Patlıcan biber kızartması (yoğurtlu)", category: "Mezeler", ingredients: ["2 patlıcan", "4 sivri biber", "1,5 su bardağı yoğurt", "1 diş sarımsak", "2 domates", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Patlıcanları dilimleyip yağ sürerek 210 °C'de 20 dakika fırınlayın.", "Biberleri tavada çevirin.", "Domatesten sos yapın.", "Tabağa patlıcan ve biberleri dizin.", "Sarımsaklı yoğurt ve domates sosla servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 210, tips: ["Fırında yapmak kızartmadan hafiftir."], serving: "Ilık.", storage: "Buzdolabında 2–3 gün."),
  GeneralRecipe(id: "n10_108", title: "Kereviz yaprağı salatası (yoğurtlu)", category: "Mezeler", ingredients: ["1 demet kereviz yaprağı ve sapı", "1 su bardağı yoğurt", "1 diş sarımsak", "2 yemek kaşığı ceviz", "1 çay kaşığı tuz"], steps: ["Kereviz yaprak ve saplarını ince doğrayın.", "Yoğurdu sarımsak ve tuzla çırpın.", "Karıştırın.", "Ceviz serpin.", "Servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Kerevizin yapraklarını değerlendirir."], serving: "Soğuk.", storage: "Aynı gün."),
  GeneralRecipe(id: "n10_109", title: "Yoğurtlu ıspanak kökü", category: "Mezeler", ingredients: ["2 demet ıspanak kökü", "1 su bardağı yoğurt", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Kökleri çok iyi yıkayın.", "3 dakika haşlayın.", "Soğutup doğrayın.", "Sarımsaklı yoğurtla karıştırın.", "Zeytinyağıyla servis edin."], minutes: 25, servings: 4, prepMinutes: 15, cookMinutes: 10, difficulty: "Kolay", tips: ["Kökler topraklı olur; birkaç suda yıkayın."], serving: "Soğuk.", storage: "Aynı gün."),
  GeneralRecipe(id: "n10_110", title: "Közlenmiş kırmızı biber ve beyaz peynir", category: "Mezeler", ingredients: ["4 köz kırmızı biber", "150 g beyaz peynir", "2 yemek kaşığı zeytinyağı", "1 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Biberleri soyup şerit doğrayın.", "Peyniri ufalayın.", "Tabağa biberleri yayın.", "Peynir, sarımsak ve kekik serpin.", "Zeytinyağı gezdirin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Rakı sofrasının klasiği."], serving: "Soğuk.", storage: "Buzdolabında 2–3 gün."),
  GeneralRecipe(id: "n10_201", title: "Ispanaklı mantarlı lazanya (vejetaryen)", category: "Makarnalar", ingredients: ["12 lazanya yaprağı", "500 g ıspanak", "250 g mantar", "250 g lor", "Beşamel: 3 yemek kaşığı tereyağı, 3 yemek kaşığı un, 3 su bardağı süt", "1,5 su bardağı rendelenmiş kaşar", "1 çay kaşığı tuz, muskat"], steps: ["Ispanak ve mantarı soteleyip lorla karıştırın.", "Beşamel hazırlayın.", "Kaba beşamel, yaprak, sebze ve kaşarı kat kat dizin.", "Folyoyla 180 °C'de 30 dakika pişirin.", "Folyoyu açıp 10 dakika kızartın."], minutes: 70, servings: 8, prepMinutes: 30, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 180, tips: ["Etsiz ve doyurucu bir lazanyadır."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
