  GeneralRecipe(id: "n10_203", title: "Domates soslu köfteli spagetti", category: "Makarnalar", ingredients: ["350 g spagetti", "300 g kıyma", "2 yemek kaşığı galeta unu", "400 g domates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, kekik"], steps: ["Kıymayı galeta unu ve tuzla yoğurup küçük köfteler yapın.", "Köfteleri tavada kızartın.", "Sarımsak ve domatesle sos yapın, köfteleri ekleyip 15 dakika pişirin.", "Spagettiyi haşlayın.", "Sosla servis edin."], minutes: 50, servings: 4, prepMinutes: 20, cookMinutes: 30, difficulty: "Kolay", tips: ["Köfteler sosu lezzetlendirir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
